# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">YAY SARKACI VE EŞ DEĞER YAY SABİTİ (T = 2π · kök(m / k))</text>\n  <rect x="20" y="45" width="215" height="198" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="127" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">Yay Sarkacı Periyodu</text>\n  <rect x="35" y="82" width="185" height="44" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="127" y="108" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">T = 2π · kök(m / k)</text>\n  <text x="35" y="146" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">m:</tspan> Cismin kütlesi (kg)</text>\n  <text x="35" y="164" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">k:</tspan> Yay sabiti (N/m)</text>\n  <text x="35" y="186" font-size="10.5" font-weight="bold" fill="#b91c1c">• Periyot (T); yer çekimi ivmesine</text>\n  <text x="43" y="202" font-size="10.5" font-weight="bold" fill="#b91c1c">(g), eğik düzlem açısına (α) ve</text>\n  <text x="43" y="218" font-size="10.5" font-weight="bold" fill="#b91c1c">genliğe (r) BAĞLI DEĞİLDİR!</text>\n  <rect x="247" y="45" width="215" height="198" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="354" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">Seri Bağlı Yaylar</text>\n  <text x="354" y="92" text-anchor="middle" font-size="10.5" fill="#14532d">Uç uca bağlanan yaylarda kuvvet</text>\n  <text x="354" y="108" text-anchor="middle" font-size="10.5" fill="#14532d">eşit, uzamalar toplamı kadardır:</text>\n  <rect x="262" y="120" width="185" height="42" rx="6" fill="#ffffff" stroke="#22c55e"/>\n  <text x="354" y="146" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">1/k_eş = 1/k₁ + 1/k₂</text>\n  <text x="262" y="182" font-size="10.5" fill="#14532d">• İki yay için: <tspan font-weight="bold">k_eş = (k₁·k₂)/(k₁+k₂)</tspan></text>\n  <text x="262" y="202" font-size="10.5" fill="#14532d">• Özdeş n yay: <tspan font-weight="bold">k_eş = k / n</tspan></text>\n  <text x="262" y="222" font-size="10.5" font-weight="bold" fill="#166534">• k_eş küçülür, periyot (T) artar.</text>\n  <rect x="475" y="45" width="205" height="198" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="577" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">Paralel Bağlı Yaylar</text>\n  <text x="577" y="92" text-anchor="middle" font-size="10.5" fill="#78350f">Cisme aynı anda bağlanan yaylarda</text>\n  <text x="577" y="108" text-anchor="middle" font-size="10.5" fill="#78350f">uzama eşit, kuvvetler toplanır:</text>\n  <rect x="490" y="120" width="175" height="42" rx="6" fill="#ffffff" stroke="#f59e0b"/>\n  <text x="577" y="146" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">k_eş = k₁ + k₂</text>\n  <text x="488" y="182" font-size="10.5" fill="#78350f">• Özdeş n yay: <tspan font-weight="bold">k_eş = n · k</tspan></text>\n  <text x="488" y="202" font-size="10.5" fill="#78350f">• Yay n eşit parçaya bölünürse</text>\n  <text x="496" y="218" font-size="10.5" font-weight="bold" fill="#92400e">her parçanın sabiti n·k olur!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">BASİT SARKAÇ VE İVMELİ SİSTEMLERDE PERİYOT (T = 2π · kök(L / g))</text>\n  <rect x="25" y="45" width="310" height="198" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">Basit Sarkaç Periyodu (α ≤ 10°)</text>\n  <rect x="65" y="80" width="230" height="42" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="180" y="106" text-anchor="middle" font-size="13.5" font-weight="bold" fill="#1d4ed8">T = 2π · kök(L / g)</text>\n  <text x="40" y="142" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">L:</tspan> Sarkacın boyu (m) ile doğru orantılı (kök L).</text>\n  <text x="40" y="162" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">g:</tspan> Çekim ivmesi (m/s²) ile ters orantılı (1 / kök g).</text>\n  <text x="40" y="182" font-size="10.5" font-weight="bold" fill="#b91c1c">• Cismin kütlesine (m) ve küçük açılarda</text>\n  <text x="48" y="198" font-size="10.5" font-weight="bold" fill="#b91c1c">salınım açısına (α) BAĞLI DEĞİLDİR!</text>\n  <text x="40" y="220" font-size="10" fill="#1e3a8a">• Kutuplara gidildikçe g artar → Periyot (T) azalır.</text>\n  <rect x="365" y="45" width="310" height="198" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#991b1b">Asansör İçi (g_etkin) Durumları</text>\n  <text x="380" y="94" font-size="10.5" fill="#7f1d1d">• <tspan font-weight="bold">Yukarı Hızlanan / Aşağı Yavaşlayan (a):</tspan></text>\n  <text x="392" y="110" font-size="11" font-weight="bold" fill="#b91c1c">g_etkin = g + a  →  Periyot (T) AZALIR</text>\n  <text x="380" y="136" font-size="10.5" fill="#7f1d1d">• <tspan font-weight="bold">Aşağı Hızlanan / Yukarı Yavaşlayan (a):</tspan></text>\n  <text x="392" y="152" font-size="11" font-weight="bold" fill="#b91c1c">g_etkin = g - a  →  Periyot (T) ARTAR</text>\n  <text x="380" y="178" font-size="10.5" fill="#7f1d1d">• <tspan font-weight="bold">Sabit Hızlı Hareket (a = 0):</tspan></text>\n  <text x="392" y="194" font-size="11" font-weight="bold" fill="#166534">g_etkin = g  →  Periyot (T) DEĞİŞMEZ</text>\n  <text x="380" y="218" font-size="10" font-weight="bold" fill="#7f1d1d">• Yay sarkacının periyodu asansör ivmesinden etkilenmez!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">ÇİVİLİ SARKAÇ PERİYODU VE SÜRE DAĞILIMI (T/6 — T/12 — T/12 — T/6)</text>\n  <rect x="20" y="45" width="320" height="198" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">Çivili (Engelli) Basit Sarkaç</text>\n  <text x="35" y="92" font-size="10.5" fill="#14532d">• Sarkaç salınımın yarısını <tspan font-weight="bold">L₁</tspan> boyuyla, diğer</text>\n  <text x="43" y="108" font-size="10.5" fill="#14532d">yarısını çiviye takılarak <tspan font-weight="bold">L₂</tspan> boyuyla yapar.</text>\n  <rect x="45" y="122" width="270" height="42" rx="6" fill="#ffffff" stroke="#22c55e"/>\n  <text x="180" y="148" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">T_sistem = (T₁ / 2) + (T₂ / 2)</text>\n  <text x="35" y="186" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">T₁ = 2π·kök(L₁/g)</tspan> ve <tspan font-weight="bold">T₂ = 2π·kök(L₂/g)</tspan></text>\n  <text x="35" y="206" font-size="10.5" fill="#14532d">• Enerji korunduğu için her iki tarafta çıkılan</text>\n  <text x="43" y="222" font-size="10.5" font-weight="bold" fill="#166534">düşey maksimum yükseklik (h) eşittir!</text>\n  <rect x="360" y="45" width="320" height="198" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">BHH\'de Bölmeler Arası Geçiş Süreleri</text>\n  <line x1="385" y1="125" x2="655" y2="125" stroke="#78350f" stroke-width="2.5"/>\n  <circle cx="385" cy="125" r="4" fill="#dc2626"/>\n  <circle cx="452" cy="125" r="4" fill="#2563eb"/>\n  <circle cx="520" cy="125" r="5" fill="#16a34a"/>\n  <circle cx="587" cy="125" r="4" fill="#2563eb"/>\n  <circle cx="655" cy="125" r="4" fill="#dc2626"/>\n  <text x="385" y="146" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">K (-r)</text>\n  <text x="452" y="146" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">L (-r/2)</text>\n  <text x="520" y="146" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">O (0)</text>\n  <text x="587" y="146" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">M (+r/2)</text>\n  <text x="655" y="146" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">N (+r)</text>\n  <text x="418" y="112" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">T / 6</text>\n  <text x="486" y="112" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">T / 12</text>\n  <text x="553" y="112" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">T / 12</text>\n  <text x="621" y="112" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">T / 6</text>\n  <text x="520" y="182" text-anchor="middle" font-size="10.5" fill="#78350f">• Uçtan dengeye (K → O): <tspan font-weight="bold">T/6 + T/12 = T/4</tspan></text>\n  <text x="520" y="202" text-anchor="middle" font-size="10.5" fill="#78350f">• Uçtan uca (K → N): <tspan font-weight="bold">T / 2</tspan></text>\n  <text x="520" y="222" font-size="10.5" fill="#78350f">• Tam bir salınım (K → N → K): <tspan font-weight="bold">T</tspan></text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
